export default function StatCard({ icon, label, value, sub, accent = 'var(--accent)', onClick }) {
  return (
    <div
      onClick={onClick}
      style={{
        background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 12,
        padding: '20px 22px', cursor: onClick ? 'pointer' : 'default',
        transition: 'border-color 0.15s',
        display: 'flex', flexDirection: 'column', gap: 8,
      }}
      onMouseEnter={e => onClick && (e.currentTarget.style.borderColor = accent)}
      onMouseLeave={e => onClick && (e.currentTarget.style.borderColor = 'var(--border)')}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <div style={{
          width: 36, height: 36, borderRadius: 9,
          background: 'color-mix(in srgb, ' + accent + ' 12%, transparent)',
          border: '1px solid color-mix(in srgb, ' + accent + ' 25%, transparent)',
          display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18,
          color: accent,
        }}>
          {icon}
        </div>
        <div style={{ fontSize: 11, color: 'var(--text-4)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.6px' }}>
          {label}
        </div>
      </div>
      <div style={{ fontSize: 28, fontWeight: 800, color: 'var(--text)', fontFamily: "'Syne',sans-serif", lineHeight: 1 }}>
        {value}
      </div>
      {sub && <div style={{ fontSize: 11, color: 'var(--text-3)' }}>{sub}</div>}
    </div>
  );
}
