import { jsPDF } from 'jspdf';

const INK = [15, 26, 36];
const MUTED = [90, 105, 120];
const LINE = [219, 226, 234];
const ACCENT = [0, 150, 105];
const HEAD_BG = [234, 244, 240];
const ZEBRA = [247, 249, 251];

const M = 14;          // page margin (mm)
const FOOTER_H = 12;

// jsPDF's built-in Helvetica only covers Latin-1; swap the common extras, drop the rest.
const clean = (v) => {
  if (v === null || v === undefined || v === '') return '—';
  return String(v)
    .replace(/[→⇒]/g, '->')
    .replace(/[“”]/g, '"').replace(/[‘’]/g, "'")
    .replace(/[^\x09\x0A\x0D\x20-\x7E\xA0-\xFF—–•·]/g, '?');
};

const download = (blob, filename) => {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};

const baseName = (filename) => filename.replace(/\.pdf$/i, '');

const csvCell = (v) => {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};

/** CSV of the same report: header block, then each table/KPI section as its own block. */
export function exportReportCsv({ title, subtitle, orgName, generatedBy, sections, filename }) {
  const lines = [];
  const row = (cells) => lines.push(cells.map(csvCell).join(','));
  row([title]);
  if (orgName) row(['Organisation', orgName]);
  row(['Period', subtitle.replace(/^Period:\s*/, '')]);
  row(['Generated', new Date().toLocaleString('en-MY') + (generatedBy ? ' by ' + generatedBy : '')]);
  for (const s of sections) {
    if (!s) continue;
    if (s.type === 'kpis') {
      lines.push(''); row([s.title || 'Summary']); row(['Metric', 'Value']);
      s.items.forEach(it => row([it.label, it.value]));
    } else if (s.type === 'chart') {
      lines.push(''); row([s.title]); row(['Day', 'Value']);
      s.data.forEach(d => row([d.label, d.value]));
    } else if (s.type === 'table') {
      lines.push(''); row([s.title]); row(s.columns.map(c => c.label));
      s.rows.forEach(r => row(r));
    } else if (s.type === 'note') {
      lines.push(''); row(['Note', s.text]);
    }
  }
  // BOM so Excel opens UTF-8 (incl. non-Latin asset names) correctly.
  download(new Blob(['﻿' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' }), baseName(filename) + '.csv');
}

/** JSON of the same report: tables become arrays of objects keyed by column label. */
export function exportReportJson({ title, subtitle, orgName, generatedBy, sections, filename }) {
  const out = {
    report: title, organisation: orgName || null, period: subtitle.replace(/^Period:\s*/, ''),
    generated_at: new Date().toISOString(), generated_by: generatedBy || null, sections: [],
  };
  for (const s of sections) {
    if (!s) continue;
    if (s.type === 'kpis') {
      out.sections.push({ title: s.title || 'Summary', type: 'summary',
        values: Object.fromEntries(s.items.map(it => [it.label, it.value])) });
    } else if (s.type === 'chart') {
      out.sections.push({ title: s.title, type: 'series', data: s.data.map(d => ({ label: d.label, value: d.value })) });
    } else if (s.type === 'table') {
      out.sections.push({ title: s.title, type: 'table',
        rows: s.rows.map(r => Object.fromEntries(s.columns.map((c, i) => [c.label, r[i] ?? null]))) });
    } else if (s.type === 'note') {
      out.sections.push({ type: 'note', text: s.text });
    }
  }
  download(new Blob([JSON.stringify(out, null, 2)], { type: 'application/json' }), baseName(filename) + '.json');
}

export function buildReportPdf({ title, subtitle, orgName, generatedBy, sections, filename }, mode = 'save') {
  const pdf = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'p' });
  const W = pdf.internal.pageSize.getWidth();
  const H = pdf.internal.pageSize.getHeight();
  const inner = W - M * 2;
  let y = M;

  const ensure = (need) => {
    if (y + need > H - FOOTER_H - 4) { pdf.addPage(); y = M; return true; }
    return false;
  };

  // ── Title block ─────────────────────────────────────────
  pdf.setFillColor(...ACCENT);
  pdf.rect(M, y, inner, 1.2, 'F');
  y += 7;
  pdf.setFont('helvetica', 'bold'); pdf.setFontSize(18); pdf.setTextColor(...INK);
  pdf.text(clean(title), M, y);
  pdf.setFont('helvetica', 'normal'); pdf.setFontSize(10); pdf.setTextColor(...MUTED);
  if (orgName) pdf.text(clean(orgName), W - M, y, { align: 'right' });
  y += 6;
  pdf.text(clean(subtitle), M, y);
  y += 5;
  const gen = `Generated ${new Date().toLocaleString('en-MY')}${generatedBy ? ' by ' + generatedBy : ''}`;
  pdf.setFontSize(8.5);
  pdf.text(clean(gen), M, y);
  y += 4;
  pdf.setDrawColor(...LINE); pdf.setLineWidth(0.3);
  pdf.line(M, y, W - M, y);
  y += 7;

  const heading = (text) => {
    ensure(14);
    pdf.setFont('helvetica', 'bold'); pdf.setFontSize(12); pdf.setTextColor(...INK);
    pdf.text(clean(text), M, y);
    y += 6;
  };

  // ── Section renderers ───────────────────────────────────
  const kpis = (items) => {
    const cols = 4, gap = 3, bw = (inner - gap * (cols - 1)) / cols, bh = 17;
    items.forEach((it, i) => {
      const c = i % cols;
      if (c === 0) ensure(bh + gap);
      const x = M + c * (bw + gap);
      pdf.setDrawColor(...LINE); pdf.setFillColor(255, 255, 255);
      pdf.roundedRect(x, y, bw, bh, 1.5, 1.5, 'FD');
      pdf.setFont('helvetica', 'normal'); pdf.setFontSize(7.5); pdf.setTextColor(...MUTED);
      pdf.text(clean(it.label).toUpperCase(), x + 3, y + 5.5, { maxWidth: bw - 6 });
      pdf.setFont('helvetica', 'bold'); pdf.setFontSize(14);
      pdf.setTextColor(...(it.color || INK));
      pdf.text(clean(it.value), x + 3, y + 13);
      if (c === cols - 1 || i === items.length - 1) y += bh + gap;
    });
    y += 4;
  };

  const chart = (data, unit) => {
    const ch = 48;
    ensure(ch + 14);
    const max = Math.max(1, ...data.map(d => d.value));
    const axisW = 14, x0 = M + axisW, plotW = inner - axisW, top = y + 2, base = y + ch;
    pdf.setFont('helvetica', 'normal'); pdf.setFontSize(7); pdf.setTextColor(...MUTED);
    for (let i = 0; i <= 4; i++) {
      const v = Math.round((max * i) / 4);
      const gy = base - ((base - top) * i) / 4;
      pdf.setDrawColor(...LINE); pdf.setLineWidth(0.15);
      pdf.line(x0, gy, x0 + plotW, gy);
      pdf.text(v.toLocaleString('en-MY'), x0 - 2, gy + 1, { align: 'right' });
    }
    const step = plotW / Math.max(1, data.length);
    const bw = Math.max(0.6, step * 0.7);
    pdf.setFillColor(...ACCENT);
    data.forEach((d, i) => {
      const h = ((base - top) * d.value) / max;
      if (h > 0) pdf.rect(x0 + i * step + (step - bw) / 2, base - h, bw, h, 'F');
    });
    const every = Math.ceil(data.length / 10);
    data.forEach((d, i) => {
      if (i % every === 0 || i === data.length - 1) {
        pdf.text(clean(d.label), x0 + i * step + step / 2, base + 4, { align: 'center' });
      }
    });
    y = base + 8;
    if (unit) {
      pdf.setFontSize(7.5);
      pdf.text(clean(unit), M, y);
      y += 4;
    }
    y += 3;
  };

  const table = (columns, rows, emptyText) => {
    pdf.setFontSize(8.5);
    const totalW = columns.reduce((s, c) => s + (c.w || 1), 0);
    const widths = columns.map(c => (inner * (c.w || 1)) / totalW);
    const pad = 1.8, lh = 3.8;

    const drawHead = () => {
      const hh = 7.5;
      pdf.setFillColor(...HEAD_BG);
      pdf.rect(M, y, inner, hh, 'F');
      pdf.setFont('helvetica', 'bold'); pdf.setFontSize(7.5); pdf.setTextColor(...INK);
      let x = M;
      columns.forEach((c, i) => {
        const tx = c.align === 'right' ? x + widths[i] - pad : x + pad;
        pdf.text(clean(c.label).toUpperCase(), tx, y + 4.8, { align: c.align === 'right' ? 'right' : 'left' });
        x += widths[i];
      });
      y += hh;
      pdf.setFont('helvetica', 'normal'); pdf.setFontSize(8.5);
    };

    ensure(16);
    drawHead();
    if (!rows.length) {
      pdf.setTextColor(...MUTED);
      pdf.text(clean(emptyText || 'No records in this range.'), M + pad, y + 5);
      y += 10;
      return;
    }
    rows.forEach((r, ri) => {
      const cells = r.map((v, i) => pdf.splitTextToSize(clean(v), widths[i] - pad * 2));
      const rh = Math.max(...cells.map(c => c.length)) * lh + pad * 2;
      if (ensure(rh)) drawHead();
      if (ri % 2 === 1) { pdf.setFillColor(...ZEBRA); pdf.rect(M, y, inner, rh, 'F'); }
      pdf.setTextColor(...INK);
      let x = M;
      cells.forEach((lines, i) => {
        const c = columns[i];
        const tx = c.align === 'right' ? x + widths[i] - pad : x + pad;
        pdf.text(lines, tx, y + pad + 2.8, { align: c.align === 'right' ? 'right' : 'left' });
        x += widths[i];
      });
      pdf.setDrawColor(...LINE); pdf.setLineWidth(0.15);
      pdf.line(M, y + rh, M + inner, y + rh);
      y += rh;
    });
    y += 7;
  };

  const note = (text) => {
    pdf.setFont('helvetica', 'italic'); pdf.setFontSize(8.5); pdf.setTextColor(...MUTED);
    const lines = pdf.splitTextToSize(clean(text), inner);
    ensure(lines.length * 4 + 2);
    pdf.text(lines, M, y);
    y += lines.length * 4 + 4;
  };

  for (const s of sections) {
    if (!s) continue;
    if (s.title) heading(s.title);
    if (s.type === 'kpis') kpis(s.items);
    else if (s.type === 'chart') chart(s.data, s.unit);
    else if (s.type === 'table') table(s.columns, s.rows, s.empty);
    else if (s.type === 'note') note(s.text);
  }

  // ── Footer on every page ────────────────────────────────
  const pages = pdf.getNumberOfPages();
  for (let p = 1; p <= pages; p++) {
    pdf.setPage(p);
    pdf.setDrawColor(...LINE); pdf.setLineWidth(0.3);
    pdf.line(M, H - FOOTER_H, W - M, H - FOOTER_H);
    pdf.setFont('helvetica', 'normal'); pdf.setFontSize(7.5); pdf.setTextColor(...MUTED);
    pdf.text(clean(`Trekify WMS · ${title}`), M, H - FOOTER_H + 5);
    pdf.text(`Page ${p} of ${pages}`, W - M, H - FOOTER_H + 5, { align: 'right' });
  }

  if (mode === 'print') {
    // Open the document itself in a new tab with the print dialog, instead of printing the dark app screen.
    pdf.autoPrint();
    const win = window.open(pdf.output('bloburl'), '_blank');
    if (!win) pdf.save(filename); // pop-up blocked: fall back to download
  } else {
    pdf.save(filename);
  }
}
